<script setup>
import { computed,ref,watch,onBeforeUnmount,onMounted } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import ProductGrid from '../components/ProductGrid.vue'
import ProductSkeleton from '../components/ProductSkeleton.vue'
import ProductFilter from '../components/ProductFilter.vue'
import EmptyState from '../components/EmptyState.vue'
import BaseIcon from '../components/BaseIcon.vue'
import { storefrontService } from '../services/storefrontService'
import { useResource } from '../composables/useResource'
import { readQuery,priceError } from '../utils/query'
const route=useRoute(), router=useRouter(), drawer=ref(false), keyword=ref(typeof route.query.keyword === 'string' ? route.query.keyword : '')
const filters=computed(() => readQuery(route.query)), validationError=computed(() => priceError(filters.value.minPrice ?? '',filters.value.maxPrice ?? ''))
const products=useResource(signal => storefrontService.products(filters.value,signal)), options=useResource(signal => storefrontService.filters(signal),0)
const data=products.data, loading=products.loading, error=products.error, filterOptions=options.data, optionsError=options.error
let searchTimer
function change(partial) { const query={ ...route.query,...partial }; delete query.page; for(const key of Object.keys(query)) if(query[key] === '' || query[key] == null || (Array.isArray(query[key]) && !query[key].length)) delete query[key]; router.push({ path:'/san-pham',query }) }
function reset() { clearTimeout(searchTimer); keyword.value=''; drawer.value=false; router.push('/san-pham') }
function page(number) { router.push({ path:'/san-pham',query:{ ...route.query,page:number+1 } }) }
watch(keyword,value => { clearTimeout(searchTimer); if(value.trim() !== (typeof route.query.keyword === 'string' ? route.query.keyword : '')) searchTimer=setTimeout(() => change({ keyword:value.trim().slice(0,120) }),300) })
watch(() => route.query,() => { keyword.value=typeof route.query.keyword === 'string' ? route.query.keyword : ''; if(!validationError.value) products.reload() },{ immediate:true })
function onViewportChange() { if(window.innerWidth > 800) drawer.value=false }
onMounted(() => window.addEventListener('resize',onViewportChange))
onBeforeUnmount(() => { clearTimeout(searchTimer); window.removeEventListener('resize',onViewportChange) })
options.reload()
</script>
<template><section class="catalog-heading"><div class="container"><nav class="breadcrumbs" aria-label="Đường dẫn"><RouterLink to="/">Trang chủ</RouterLink><span>/</span><span>Sản phẩm</span></nav><span class="eyebrow">SMASHSTEP COLLECTION</span><h1>Tất cả sản phẩm</h1><p>Chọn phong cách, tìm đôi giày dành riêng cho bạn.</p></div></section><div class="container catalog-layout"><ProductFilter :options="filterOptions" :filters="filters" :open="drawer" @change="change" @reset="reset" @close="drawer=false" /><section class="catalog-results" aria-label="Danh sách sản phẩm"><div class="catalog-toolbar"><div class="catalog-result-count" aria-live="polite"><strong>{{ data?.totalElements ?? '—' }}</strong> sản phẩm<span v-if="loading && data" class="updating"> · Đang cập nhật</span></div><button class="button button-outline filter-toggle" :aria-expanded="drawer" aria-controls="catalogue-filter" @click="drawer=true"><BaseIcon name="filter" /> Bộ lọc</button><label class="page-size-control">Hiển thị<select aria-label="Số sản phẩm mỗi trang" :value="filters.size" @change="change({ size:$event.target.value })"><option :value="6">6</option><option :value="12">12</option><option :value="24">24</option></select></label><label class="sort-control">Sắp xếp<select aria-label="Sắp xếp sản phẩm" :value="filters.sort" @change="change({ sort:$event.target.value })"><option value="newest">Mới nhất</option><option value="priceAsc">Giá thấp đến cao</option><option value="priceDesc">Giá cao đến thấp</option></select></label></div><form class="catalog-search" role="search" @submit.prevent="change({ keyword:keyword.trim() })"><BaseIcon name="search" /><label class="sr-only" for="catalog-keyword">Tìm theo tên hoặc mã sản phẩm</label><input id="catalog-keyword" v-model="keyword" maxlength="120" type="search" placeholder="Tìm theo tên hoặc mã sản phẩm…"><button class="text-button" type="submit">Tìm kiếm</button></form><p v-if="optionsError" class="inline-error" role="alert">Không tải được bộ lọc. <button class="text-button" @click="options.reload">Thử lại</button></p><EmptyState v-if="validationError" :title="validationError" error action="Xóa bộ lọc" @action="reset" /><EmptyState v-else-if="error" :title="error" error action="Thử lại" @action="products.reload" /><ProductSkeleton v-else-if="loading && !data" :count="12" /><ProductGrid v-else-if="data?.content.length" :products="data.content" /><EmptyState v-else title="Không tìm thấy sản phẩm phù hợp." description="Thử từ khóa khác hoặc điều chỉnh bộ lọc của bạn." action="Xóa bộ lọc" @action="reset" /><nav v-if="data?.totalPages > 1 && !error && !validationError" class="pagination" aria-label="Phân trang sản phẩm"><button class="icon-button" :disabled="data.number === 0 || loading" aria-label="Trang trước" @click="page(data.number-1)"><BaseIcon name="left" /></button><button v-for="n in data.totalPages" :key="n" :class="{ selected:data.number === n-1 }" :aria-label="'Trang ' + n" :aria-current="data.number === n-1 ? 'page' : undefined" :disabled="loading" @click="page(n-1)">{{ n }}</button><button class="icon-button" :disabled="data.number >= data.totalPages-1 || loading" aria-label="Trang tiếp theo" @click="page(data.number+1)"><BaseIcon name="right" /></button></nav></section></div></template>
